{"file_text": ".settings-container {
    display: flex;
    min-height: calc(100vh - 4rem);
    max-width: 1200px;
    margin: 0 auto;
    gap: 2rem;
    padding: 2rem;
}

/* Sidebar */
.settings-sidebar {
    width: 220px;
    flex-shrink: 0;
}

.settings-sidebar ul {
    list-style: none;
    padding: 0;
