    font-weight: 500;
    color: #555;
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.settings-sidebar li:hover {
    background-color: #f0f0f0;
    color: #111;
}

.settings-sidebar li.active {
    background-color: #4f46e5;
    color: white;
}

.nav-icon {
    font-size: 1.1rem;
}

/* Content */
.settings-content {
    flex: 1;
    position: relative;
}

.settings-content h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
    color: #1a1a1a;
}

.settings-content h3 {
    margin-top: 1.5rem;
    margin-bottom: 0.75rem;
    color: #333;
}

/* Loading */
.loading {
    display: flex;
    justify-content: center;
    align-items: center;
    height: 200px;
    color: #888;
    font-size: 1.1rem;
}

/* Forms */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    color: #444;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="password"],
.form-group textarea,
.form-group select {
