    background-color: #e5e7eb;
}

.btn-danger {
    padding: 0.6rem 1.5rem;
    background-color: #dc2626;
    color: white;
    border: none;
    border-radius: 6px;
    cursor: pointer;
    font-weight: 500;
    font-size: 0.9rem;
}

.btn-danger:hover {
    background-color: #b91c1c;
}

.btn-danger-sm {
    padding: 0.3rem 0.75rem;
    background-color: #dc2626;
    color: white;
    border: none;
