@page "/settings"
@rendermode InteractiveServer
@using sv_e83ad769ccac4e7f86132e947edd7833.Services
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <ul>
            <li class="@(ActiveSection == "Profile" ? "active" : "")" @onclick='() => SetSection("Profile")'>
                <span class="nav-icon">👤</span> Profile
            </li>
            <li class="@(ActiveSection == "Notifications" ? "active" : "")" @onclick='() => SetSection("Notifications")'>
                <span class="nav-icon">🔔</span> Notifications
            </li>
            <li class="@(ActiveSection == "Security" ? "active" : "")" @onclick='() => SetSection("Security")'>
                <span class="nav-icon">🔒</span> Security
            </li>
            <li class="@(ActiveSection == "Appearance" ? "active" : "")" @onclick='() => SetSection("Appearance")'>
                <span class="nav-icon">🎨</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (IsLoading)
        {
            <div class="loading">Loading...</div>
        }
        else
        {
            @switch (ActiveSection)
            {
                case "Profile":
                    @RenderProfileSection()
                    break;
                case "Notifications":
                    @RenderNotificationsSection()
                    break;
                case "Security":
                    @RenderSecuritySection()
                    break;
                case "Appearance":
                    @RenderAppearanceSection()
                    break;
            }
        }

        @if (!string.IsNullOrEmpty(ToastMessage))
        {
            <div class="toast @ToastType">
                @ToastMessage
            </div>
        }
    </main>
</div>

@code {
    private string ActiveSection { get; set; } = "Profile";
    private bool IsLoading { get; set; } = true;

    // Toast
    private string? ToastMessage { get; set; }
    private string ToastType { get; set; } = "success";
    private CancellationTokenSource? _toastCts;

    // Profile
    private string ProfileDisplayName { get; set; } = "";
    private string ProfileEmail { get; set; } = "";
    private string ProfileAvatarUrl { get; set; } = "";
    private string ProfileBio { get; set; } = "";
    private UserProfile? _savedProfile;

    // Notifications
    private bool EmailNotifications { get; set; }
    private bool PushNotifications { get; set; }
    private bool WeeklyDigest { get; set; }
    private List<string> MutedChannels { get; set; } = new();
    private Dictionary<string, bool> ChannelMuteStates { get; set; } = new();

    // Security
    private SecuritySettings? SecurityData { get; set; }
    private bool ShowChangePassword { get; set; }
    private string CurrentPassword { get; set; } = "";
    private string NewPassword { get; set; } = "";
    private string ConfirmPassword { get; set; } = "";
    private string? PasswordError { get; set; }
    private bool TwoFactorEnabled { get; set; }
    private string? SessionToRevoke { get; set; }

    // Appearance
    private string SelectedTheme { get; set; } = "Light";
    private string SelectedFontSize { get; set; } = "Medium";
    private string SelectedLanguage { get; set; } = "English";
    private bool CompactMode { get; set; }

    private readonly string[] AvailableLanguages = { "English", "Spanish", "French", "German", "Japanese", "Chinese", "Portuguese" };
    private const string CurrentSessionId = "session-1";

    protected override async Task OnInitializedAsync()
    {
        await LoadSectionData();
    }

    private async Task SetSection(string section)
    {
        ActiveSection = section;
        IsLoading = true;
        await LoadSectionData();
    }

    private async Task LoadSectionData()
    {
        switch (ActiveSection)
        {
            case "Profile":
                var profile = await SettingsService.GetProfileAsync();
                _savedProfile = profile;
                ProfileDisplayName = profile.DisplayName;
                ProfileEmail = profile.Email;
                ProfileAvatarUrl = profile.AvatarUrl;
                ProfileBio = profile.Bio;
                break;
            case "Notifications":
                var prefs = await SettingsService.GetNotificationPrefsAsync();
                EmailNotifications = prefs.EmailNotifications;
                PushNotifications = prefs.PushNotifications;
                WeeklyDigest = prefs.WeeklyDigest;
                MutedChannels = prefs.MutedChannels;
                ChannelMuteStates = MutedChannels.ToDictionary(c => c, _ => true);
                break;
            case "Security":
                SecurityData = await SettingsService.GetSecuritySettingsAsync();
                TwoFactorEnabled = SecurityData.TwoFactorEnabled;
                ShowChangePassword = false;
                CurrentPassword = "";
                NewPassword = "";
                ConfirmPassword = "";
                PasswordError = null;
                break;
            case "Appearance":
                var appearance = await SettingsService.GetAppearanceAsync();
                SelectedTheme = appearance.Theme;
                SelectedFontSize = appearance.FontSize;
                SelectedLanguage = appearance.Language;
                CompactMode = appearance.CompactMode;
                break;
        }
        IsLoading = false;
    }

    private async Task ShowToast(string message, string type = "success")
    {
        _toastCts?.Cancel();
        _toastCts = new CancellationTokenSource();
        ToastMessage = message;
        ToastType = type;
        StateHasChanged();

        var token = _toastCts.Token;
        try
        {
            await Task.Delay(3000, token);
            ToastMessage = null;
            StateHasChanged();
        }
        catch (TaskCanceledException) { }
    }

    // Profile actions
    private async Task SaveProfile()
    {
        var profile = new UserProfile(ProfileDisplayName, ProfileEmail, ProfileAvatarUrl, ProfileBio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        await ShowToast("Profile saved successfully!");
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is not null)
        {
            ProfileDisplayName = _savedProfile.DisplayName;
            ProfileEmail = _savedProfile.Email;
            ProfileAvatarUrl = _savedProfile.AvatarUrl;
            ProfileBio = _savedProfile.Bio;
        }
    }

    // Notifications actions
    private async Task SaveNotifications()
    {
        var mutedChannels = ChannelMuteStates.Where(kv => kv.Value).Select(kv => kv.Key).ToList();
        var prefs = new NotificationPrefs(EmailNotifications, PushNotifications, WeeklyDigest, mutedChannels);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        await ShowToast("Notification preferences saved!");
    }

    private void ToggleChannelMute(string channel, bool muted)
    {
        ChannelMuteStates[channel] = muted;
    }

    // Security actions
    private async Task UpdatePassword()
    {
        PasswordError = null;
        if (string.IsNullOrWhiteSpace(CurrentPassword))
        {
            PasswordError = "Current password is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(NewPassword) || NewPassword.Length < 8)
        {
            PasswordError = "New password must be at least 8 characters.";
            return;
        }
        if (NewPassword != ConfirmPassword)
        {
            PasswordError = "Passwords do not match.";
            return;
        }

        await SettingsService.ChangePasswordAsync(CurrentPassword, NewPassword);
        CurrentPassword = "";
        NewPassword = "";
        ConfirmPassword = "";
        ShowChangePassword = false;
        SecurityData = await SettingsService.GetSecuritySettingsAsync();
        await ShowToast("Password updated successfully!");
    }

    private void RequestRevokeSession(string sessionId)
    {
        SessionToRevoke = sessionId;
    }

    private async Task ConfirmRevokeSession()
    {
        if (SessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(SessionToRevoke);
            SecurityData = await SettingsService.GetSecuritySettingsAsync();
            SessionToRevoke = null;
            await ShowToast("Session revoked.");
        }
    }

    private void CancelRevoke()
    {
        SessionToRevoke = null;
    }

    // Appearance actions
    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(SelectedTheme, SelectedFontSize, SelectedLanguage, CompactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        await ShowToast("Appearance settings saved!");
    }

    // Render helpers
    private RenderFragment RenderProfileSection() => __builder =>
    {
        <h2>Profile Settings</h2>

        <div class="avatar-section">
            <div class="avatar-preview">
                <img src="@ProfileAvatarUrl" alt="Avatar" />
            </div>
            <div class="avatar-url">
                <label>Avatar URL</label>
                <input type="text" @bind="ProfileAvatarUrl" />
            </div>
        </div>

        <div class="form-group">
            <label>Display Name</label>
            <input type="text" @bind="ProfileDisplayName" />
        </div>

        <div class="form-group">
            <label>Email</label>
            <input type="email" @bind="ProfileEmail" />
        </div>

        <div class="form-group">
            <label>Bio</label>
            <textarea rows="4" @bind="ProfileBio"></textarea>
        </div>

        <div class="button-group">
            <button class="btn-primary" @onclick="SaveProfile">Save Changes</button>
            <button class="btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
        </div>
    };

    private RenderFragment RenderNotificationsSection() => __builder =>
    {
        <h2>Notification Preferences</h2>

        <div class="toggle-group">
            <div class="toggle-item">
                <label class="toggle-label">
                    <input type="checkbox" @bind="EmailNotifications" />
                    <span class="toggle-switch"></span>
                    Email Notifications
                </label>
            </div>
            <div class="toggle-item">
                <label class="toggle-label">
                    <input type="checkbox" @bind="PushNotifications" />
                    <span class="toggle-switch"></span>
                    Push Notifications
                </label>
            </div>
            <div class="toggle-item">
                <label class="toggle-label">
                    <input type="checkbox" @bind="WeeklyDigest" />
                    <span class="toggle-switch"></span>
                    Weekly Digest
                </label>
            </div>
        </div>

        <h3>Muted Channels</h3>
        <div class="channel-list">
            @foreach (var channel in ChannelMuteStates.Keys.ToList())
            {
                var ch = channel;
                <label class="channel-item">
                    <input type="checkbox" checked="@ChannelMuteStates[ch]"
                           @onchange="(e) => ToggleChannelMute(ch, (bool)(e.Value ?? false))" />
                    <span>#@ch</span>
                </label>
            }
        </div>

        <div class="button-group">
            <button class="btn-primary" @onclick="SaveNotifications">Save Preferences</button>
        </div>
    };

    private RenderFragment RenderSecuritySection() => __builder =>
    {
        <h2>Security Settings</h2>

        <div class="security-section">
            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => ShowChangePassword = !ShowChangePassword">
                    <span>Change Password</span>
                    <span class="expand-icon">@(ShowChangePassword ? "▼" : "▶")</span>
                </button>
                @if (ShowChangePassword)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label>Current Password</label>
                            <input type="password" @bind="CurrentPassword" />
                        </div>
                        <div class="form-group">
                            <label>New Password</label>
                            <input type="password" @bind="NewPassword" />
                        </div>
                        <div class="form-group">
                            <label>Confirm New Password</label>
                            <input type="password" @bind="ConfirmPassword" />
                        </div>
                        @if (!string.IsNullOrEmpty(PasswordError))
                        {
                            <div class="error-message">@PasswordError</div>
                        }
                        <button class="btn-primary" @onclick="UpdatePassword">Update Password</button>
                    </div>
                }
            </div>

            <div class="two-factor-section">
                <h3>Two-Factor Authentication</h3>
                <div class="status-row">
                    <label class="toggle-label">
                        <input type="checkbox" @bind="TwoFactorEnabled" />
                        <span class="toggle-switch"></span>
                        Enable Two-Factor Authentication
                    </label>
                    <span class="status-indicator @(TwoFactorEnabled ? "enabled" : "disabled")">
                        @(TwoFactorEnabled ? "● Enabled" : "○ Disabled")
                    </span>
                </div>
                @if (SecurityData?.LastPasswordChange.HasValue == true)
                {
                    <p class="info-text">Last password change: @SecurityData.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                }
            </div>

            <div class="sessions-section">
                <h3>Active Sessions</h3>
                <table class="sessions-table">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th>Action</th>
                        </tr>
                    </thead>
                    <tbody>
                        @if (SecurityData?.Sessions is not null)
                        {
                            @foreach (var session in SecurityData.Sessions)
                            {
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@FormatLastActive(session.LastActive)</td>
                                    <td>
                                        @if (session.Id == CurrentSessionId)
                                        {
                                            <span class="current-session">Current</span>
                                        }
                                        else
                                        {
                                            <button class="btn-danger-sm" @onclick="() => RequestRevokeSession(session.Id)">Revoke</button>
                                        }
                                    </td>
                                </tr>
                            }
                        }
                    </tbody>
                </table>
            </div>
        </div>

        @if (SessionToRevoke is not null)
        {
            <div class="modal-overlay">
                <div class="modal-dialog">
                    <h4>Confirm Revoke Session</h4>
                    <p>Are you sure you want to revoke this session? The device will be signed out immediately.</p>
                    <div class="button-group">
                        <button class="btn-danger" @onclick="ConfirmRevokeSession">Revoke Session</button>
                        <button class="btn-secondary" @onclick="CancelRevoke">Cancel</button>
                    </div>
                </div>
            </div>
        }
    };

    private RenderFragment RenderAppearanceSection() => __builder =>
    {
        <h2>Appearance Settings</h2>

        <div class="appearance-options">
            <div class="form-group">
                <label><strong>Theme</strong></label>
                <div class="radio-group">
                    <label><input type="radio" name="theme" value="Light" checked="@(SelectedTheme == "Light")" @onchange='() => SelectedTheme = "Light"' /> Light</label>
                    <label><input type="radio" name="theme" value="Dark" checked="@(SelectedTheme == "Dark")" @onchange='() => SelectedTheme = "Dark"' /> Dark</label>
                    <label><input type="radio" name="theme" value="System" checked="@(SelectedTheme == "System")" @onchange='() => SelectedTheme = "System"' /> System</label>
                </div>
            </div>

            <div class="form-group">
                <label><strong>Font Size</strong></label>
                <div class="radio-group">
                    <label><input type="radio" name="fontsize" value="Small" checked="@(SelectedFontSize == "Small")" @onchange='() => SelectedFontSize = "Small"' /> Small</label>
                    <label><input type="radio" name="fontsize" value="Medium" checked="@(SelectedFontSize == "Medium")" @onchange='() => SelectedFontSize = "Medium"' /> Medium</label>
                    <label><input type="radio" name="fontsize" value="Large" checked="@(SelectedFontSize == "Large")" @onchange='() => SelectedFontSize = "Large"' /> Large</label>
                </div>
            </div>

            <div class="form-group">
                <label><strong>Language</strong></label>
                <select @bind="SelectedLanguage">
                    @foreach (var lang in AvailableLanguages)
                    {
                        <option value="@lang">@lang</option>
                    }
                </select>
            </div>

            <div class="toggle-item">
                <label class="toggle-label">
                    <input type="checkbox" @bind="CompactMode" />
                    <span class="toggle-switch"></span>
                    <strong>Compact Mode</strong>
                </label>
            </div>
        </div>

        <div class="preview-area">
            <h3>Live Preview</h3>
            <div class="preview-box @GetPreviewClasses()">
                <div class="preview-header">Settings Dashboard</div>
                <div class="preview-body">
                    <p>This is a preview of your selected appearance settings.</p>
                    <p>Theme: <strong>@SelectedTheme</strong> | Font: <strong>@SelectedFontSize</strong> | Language: <strong>@SelectedLanguage</strong></p>
                    @if (CompactMode)
                    {
                        <p><em>Compact mode is enabled — reduced spacing applied.</em></p>
                    }
                </div>
            </div>
        </div>

        <div class="button-group">
            <button class="btn-primary" @onclick="SaveAppearance">Save</button>
        </div>
    };

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add($"theme-{SelectedTheme.ToLower()}");
        classes.Add($"font-{SelectedFontSize.ToLower()}");
        if (CompactMode) classes.Add("compact");
        return string.Join(" ", classes);
    }

    private string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} minutes ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hours ago";
        return $"{(int)diff.TotalDays} days ago";
    }
}

